/* @autogenerated */
package net.civeira.phylax.feature.oauth.tokensecurity.application;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Duration;
import java.time.Instant;
import java.util.Base64;
import java.util.List;
import java.util.Optional;

import org.jose4j.jwk.PublicJsonWebKey;
import org.jose4j.jws.JsonWebSignature;
import org.jose4j.jwt.JwtClaims;
import org.jose4j.lang.JoseException;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.oauth.client.domain.gateway.JwtReplayGateway;

/**
 * Verifies a DPoP proof (RFC 9449 §4.3, task 3.6) and returns the thumbprint of its key.
 *
 * <ul>
 * <li>{@code typ: dpop+jwt}, an asymmetric {@link #ALGORITHMS algorithm} and a public {@code jwk}
 * in the header; the signature is checked with that key;</li>
 * <li>{@code htm} and {@code htu} are the method and URL of the request (without query nor
 * fragment);</li>
 * <li>{@code iat} within a minute of now, and {@code jti} used only once for that key;</li>
 * <li>with an access token, {@code ath} is its SHA-256.</li>
 * </ul>
 */
@Slf4j
@ApplicationScoped
@RequiredArgsConstructor
public class DpopProofVerifier {

  /**
   * Algorithms of a DPoP proof.
   */
  public static final List<String> ALGORITHMS = List.of("RS256", "ES256", "PS256");
  private static final Duration WINDOW = Duration.ofSeconds(60);
  private static final String PURPOSE = "dpop";

  private final JwtReplayGateway replays;

  /**
   * Verifies a proof.
   *
   * @param tenant tenant of the endpoint
   * @param proof the {@code DPoP} header
   * @param method HTTP method of the request
   * @param url URL of the request
   * @param accessToken access token presented with the proof, null at the token endpoint
   * @return the base64url SHA-256 thumbprint of the proof key ({@code cnf.jkt}), empty when invalid
   */
  public Optional<String> verify(String tenant, String proof, String method, String url,
      String accessToken) {
    if (proof == null || proof.isBlank()) {
      return Optional.empty();
    }
    try {
      JsonWebSignature jws = new JsonWebSignature();
      jws.setCompactSerialization(proof);
      if (!"dpop+jwt".equals(jws.getHeader("typ"))
          || !ALGORITHMS.contains(jws.getAlgorithmHeaderValue())) {
        return rejected("header");
      }
      PublicJsonWebKey jwk = jws.getJwkHeader();
      if (jwk == null || jwk.getPrivateKey() != null) {
        return rejected("jwk");
      }
      jws.setKey(jwk.getPublicKey());
      if (!jws.verifySignature()) {
        return rejected("signature");
      }
      JwtClaims claims = JwtClaims.parse(jws.getPayload());
      if (!method.equalsIgnoreCase(claims.getStringClaimValue("htm"))
          || !withoutQuery(url).equals(withoutQuery(claims.getStringClaimValue("htu")))) {
        return rejected("htm/htu");
      }
      if (claims.getIssuedAt() == null) {
        return rejected("iat");
      }
      Instant iat = Instant.ofEpochSecond(claims.getIssuedAt().getValue());
      Instant now = Instant.now();
      if (iat.isBefore(now.minus(WINDOW)) || iat.isAfter(now.plus(WINDOW))) {
        return rejected("iat");
      }
      if (accessToken != null && !hash(accessToken).equals(claims.getStringClaimValue("ath"))) {
        return rejected("ath");
      }
      String jti = claims.getJwtId();
      String jkt = jwk.calculateBase64urlEncodedThumbprint("SHA-256");
      if (jti == null || jti.isBlank()
          || !replays.firstUse(tenant, jkt, PURPOSE, jti, iat.plus(WINDOW.multipliedBy(2)))) {
        return rejected("jti");
      }
      return Optional.of(jkt);
    } catch (JoseException | org.jose4j.jwt.MalformedClaimException
        | org.jose4j.jwt.consumer.InvalidJwtException | RuntimeException ex) {
      return rejected(ex.getMessage());
    }
  }

  /**
   * Base64url SHA-256 of an access token, the {@code ath} of its proofs.
   *
   * @param accessToken token
   * @return hash
   */
  public static String hash(String accessToken) {
    try {
      return Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest
          .getInstance("SHA-256").digest(accessToken.getBytes(StandardCharsets.US_ASCII)));
    } catch (NoSuchAlgorithmException ex) {
      throw new IllegalStateException(ex);
    }
  }

  private static String withoutQuery(String url) {
    if (url == null) {
      return "";
    }
    int cut = url.indexOf('?');
    int hash = url.indexOf('#');
    int end = cut < 0 ? hash : hash < 0 ? cut : Math.min(cut, hash);
    return end < 0 ? url : url.substring(0, end);
  }

  private static Optional<String> rejected(String reason) {
    log.info("DPoP proof rejected: {}", reason);
    return Optional.empty();
  }
}
